/* Nexus docs: a small client-side app. No build step.
 * Content lives in documentation/**.md, indexed in documentation/manifest.json
 * (generated by scripts/build-index.mjs). Routing uses the URL hash so it works
 * on GitHub Pages without any server rewrites.
 */
(function () {
  "use strict";

  // ---------- config (edit these) ----------
  var CONFIG = {
    siteName: "Nexus docs",
    repo: "guygun1/Nexus.github.io", // used for the "Edit this page" and "Source" links; set to "" to hide them
    branch: "main",
    contentDir: "docs/documentation"
  };
  var CONTENT = "documentation/";

  var view = document.getElementById("view");
  var topInput = document.getElementById("q-top");
  var DATA = null;
  var renderToken = 0;
  var prevHash = "#/";
  var tocObserver = null;
  var currentDir = ""; // folder of the page being rendered, for relative links

  // ---------- helpers ----------
  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  function escRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
  function humanize(s) {
    s = s.replace(/[_-]+/g, " ").trim();
    return s.charAt(0).toUpperCase() + s.slice(1);
  }
  function slugify(s) {
    return s.toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu, "").trim().replace(/\s+/g, "-") || "section";
  }
  function encPath(p) { return p.split("/").map(encodeURIComponent).join("/"); }
  function pageHref(id) { return "#/" + encPath(id); }
  function dirHref(dir) { return dir ? "#/" + encPath(dir) + "/" : "#/"; }
  function tagHref(tag) { return "#/search?tag=" + encodeURIComponent(tag); }
  function searchHref(q, tags) {
    var p = new URLSearchParams();
    if (q) p.set("q", q);
    (tags || []).forEach(function (t) { p.append("tag", t); });
    var s = p.toString();
    return "#/search" + (s ? "?" + s : "");
  }
  function dirOf(id) { var i = id.lastIndexOf("/"); return i < 0 ? "" : id.slice(0, i); }
  function baseOf(id) { var i = id.lastIndexOf("/"); return i < 0 ? id : id.slice(i + 1); }
  var collator = new Intl.Collator("en", { numeric: true, sensitivity: "base" });
  function plural(n, one, many) { return n + " " + (n === 1 ? one : many || one + "s"); }

  // ---------- data ----------
  function prepare(manifest) {
    var pages = manifest.pages || [];
    var categories = manifest.categories || {};
    var byId = {};
    var tagCounts = {};
    var dirs = {};
    pages.forEach(function (p) {
      p.dir = dirOf(p.id);
      p.name = baseOf(p.id);
      p.tags = p.tags || [];
      p._t = p.title.toLowerCase();
      p._h = (p.headings || []).join(" ").toLowerCase();
      p._path = p.id.replace(/[_\/-]+/g, " ").toLowerCase();
      p._d = (p.description || "").toLowerCase();
      p._x = (p.text || "").toLowerCase();
      byId[p.id] = p;
      p.tags.forEach(function (t) { tagCounts[t] = (tagCounts[t] || 0) + 1; });
      var parts = p.dir ? p.dir.split("/") : [];
      for (var i = 1; i <= parts.length; i++) dirs[parts.slice(0, i).join("/")] = true;
    });
    Object.keys(categories).forEach(function (d) {
      var parts = d.split("/");
      for (var i = 1; i <= parts.length; i++) dirs[parts.slice(0, i).join("/")] = true;
    });
    return { pages: pages, categories: categories, byId: byId, tagCounts: tagCounts, dirs: dirs };
  }
  function dirTitle(dir) {
    var c = DATA.categories[dir];
    return (c && c.title) || humanize(baseOf(dir));
  }
  function dirInfo(dir) { return DATA.categories[dir] || {}; }
  function sortPages(list) {
    return list.slice().sort(function (a, b) {
      var am = a.name === "main" ? 0 : 1, bm = b.name === "main" ? 0 : 1;
      if (am !== bm) return am - bm;
      var ao = a.order == null ? 1e9 : a.order, bo = b.order == null ? 1e9 : b.order;
      if (ao !== bo) return ao - bo;
      return collator.compare(a.title, b.title);
    });
  }
  function pagesIn(dir) { return sortPages(DATA.pages.filter(function (p) { return p.dir === dir; })); }
  function countUnder(dir) {
    var pre = dir ? dir + "/" : "";
    return DATA.pages.filter(function (p) { return p.id.indexOf(pre) === 0; }).length;
  }
  function childDirs(dir) {
    var pre = dir ? dir + "/" : "";
    return Object.keys(DATA.dirs).filter(function (d) {
      return d.indexOf(pre) === 0 && d.slice(pre.length).indexOf("/") < 0 && d !== dir;
    }).sort(function (a, b) {
      var ao = dirInfo(a).order, bo = dirInfo(b).order;
      ao = ao == null ? 1e9 : ao; bo = bo == null ? 1e9 : bo;
      return ao !== bo ? ao - bo : collator.compare(dirTitle(a), dirTitle(b));
    });
  }
  function sortedTags() {
    return Object.keys(DATA.tagCounts).sort(function (a, b) {
      return DATA.tagCounts[b] - DATA.tagCounts[a] || collator.compare(a, b);
    });
  }

  // ---------- search ----------
  function parseQuery(raw) {
    var tags = [], words = [];
    raw.trim().split(/\s+/).forEach(function (tok) {
      if (!tok) return;
      var m = tok.match(/^tag:(.+)$/i);
      if (m) tags.push(m[1].toLowerCase());
      else tok.toLowerCase().split(/[^\p{L}\p{N}]+/u).forEach(function (w) { if (w) words.push(w); });
    });
    return { words: words, tags: tags };
  }
  function scoreWord(p, w) {
    var s = 0;
    var starts = new RegExp("(^|[^\\p{L}\\p{N}])" + escRe(w), "u");
    if (starts.test(p._t)) s += 10; else if (p._t.indexOf(w) >= 0) s += 6;
    if (p.tags.some(function (t) { return t === w || t.indexOf(w) === 0; })) s += 8;
    if (p._h.indexOf(w) >= 0) s += 5;
    if (p._path.indexOf(w) >= 0) s += 4;
    if (p._d.indexOf(w) >= 0) s += 3;
    var c = 0, i = -1;
    while (c < 4 && (i = p._x.indexOf(w, i + 1)) >= 0) c++;
    return s + c;
  }
  function search(words, tags) {
    var pool = DATA.pages.filter(function (p) {
      return tags.every(function (t) { return p.tags.indexOf(t) >= 0; });
    });
    if (!words.length) {
      return { partial: false, hits: pool.map(function (p) { return { p: p, s: 1 }; })
        .sort(function (a, b) { return collator.compare(a.p.title, b.p.title); }) };
    }
    function run(mode) {
      var out = [];
      pool.forEach(function (p) {
        var total = 0, ok = true;
        words.forEach(function (w) {
          var s = scoreWord(p, w);
          if (s === 0) ok = false; else total += s;
        });
        if (mode === "and" ? ok : total > 0) out.push({ p: p, s: total });
      });
      return out.sort(function (a, b) { return b.s - a.s || collator.compare(a.p.title, b.p.title); });
    }
    var hits = run("and");
    if (hits.length || words.length < 2) return { partial: false, hits: hits };
    return { partial: true, hits: run("or") };
  }
  function highlight(text, words) {
    if (!words.length) return esc(text);
    var re = new RegExp("(" + words.map(escRe).join("|") + ")", "gi");
    return text.split(re).map(function (part, i) { return i % 2 ? "<mark>" + esc(part) + "</mark>" : esc(part); }).join("");
  }
  function snippet(p, words) {
    var text = p.text || "";
    var low = p._x;
    var at = -1;
    for (var i = 0; i < words.length && at < 0; i++) at = low.indexOf(words[i]);
    if (at < 0) return p.description || text.slice(0, 160);
    var start = Math.max(0, at - 70);
    var end = Math.min(text.length, at + 130);
    return (start > 0 ? "…" : "") + text.slice(start, end).trim() + (end < text.length ? "…" : "");
  }
  function crumbPath(p) {
    var parts = p.dir ? p.dir.split("/") : [];
    var names = parts.map(function (_, i) { return dirTitle(parts.slice(0, i + 1).join("/")); });
    return names.join(" / ");
  }

  // ---------- routing ----------
  function parseRoute() {
    var raw = location.hash.replace(/^#/, "") || "/";
    var qi = raw.indexOf("?");
    var pathPart = qi < 0 ? raw : raw.slice(0, qi);
    var params = new URLSearchParams(qi < 0 ? "" : raw.slice(qi + 1));
    var segs = pathPart.split("/").filter(Boolean).map(function (s) {
      try { return decodeURIComponent(s); } catch (e) { return s; }
    });
    var path = segs.join("/");
    var trailing = /\/$/.test(pathPart) && path !== "";
    if (!path) return { kind: "home", params: params };
    if (path === "search") return { kind: "search", params: params };
    if (!trailing && DATA.byId[path]) return { kind: "page", id: path, params: params };
    if (DATA.dirs[path]) return { kind: "category", dir: path, params: params };
    if (DATA.byId[path]) return { kind: "page", id: path, params: params };
    return { kind: "missing", path: path, params: params };
  }

  function setTitle(t) { document.title = t ? t + " - " + CONFIG.siteName : CONFIG.siteName; }

  function render() {
    var token = ++renderToken;
    if (tocObserver) { tocObserver.disconnect(); tocObserver = null; }
    var route = parseRoute();
    document.body.classList.remove("sidebar-open");
    document.body.classList.toggle("is-home", route.kind === "home");
    topInput.value = route.kind === "search" ? (route.params.get("q") || "") : "";
    var done;
    switch (route.kind) {
      case "home": done = renderHome(); break;
      case "search": done = renderSearch(route); break;
      case "category": done = renderCategory(route.dir); break;
      case "page": done = renderPage(route.id, token); break;
      default: done = renderMissing(route.path);
    }
    Promise.resolve(done).then(function () {
      if (token !== renderToken) return;
      var h = route.params.get("h");
      var target = h && document.getElementById(h);
      if (target) target.scrollIntoView(); else window.scrollTo(0, 0);
    });
  }

  // ---------- views ----------
  var ICON_SEARCH = '<svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true"><path d="M14.386 14.386l4.088 4.088-4.088-4.088A7.533 7.533 0 1 1 3.733 3.733a7.533 7.533 0 0 1 10.653 10.653z" stroke="currentColor" fill="none" stroke-width="2" stroke-linecap="round"/></svg>';
  var ICON_HOME = '<svg width="16" height="16" viewBox="0 0 24 24" aria-hidden="true"><path d="M10 19v-5h4v5c0 .55.45 1 1 1h3c.55 0 1-.45 1-1v-7h1.7c.46 0 .68-.57.33-.87L12.67 3.6c-.38-.34-.96-.34-1.34 0l-8.36 7.53c-.34.3-.13.87.33.87H5v7c0 .55.45 1 1 1h3c.55 0 1-.45 1-1z" fill="currentColor"/></svg>';
  var ICON_EDIT = '<svg width="14" height="14" viewBox="0 0 40 40" aria-hidden="true"><g fill="currentColor"><path d="m34.5 11.7-3 3.1-6.3-6.3 3.1-3q.5-.5 1.2-.5t1.1.5l3.9 3.9q.5.4.5 1.1t-.5 1.2zm-29.5 17.1 18.4-18.5 6.3 6.3-18.4 18.4h-6.3v-6.2z"/></g></svg>';

  function tagBadge(t, href, on, label) {
    var n = DATA.tagCounts[t];
    return '<a class="tag' + (on ? " is-on" : "") + '" href="' + href + '"' + (label ? ' title="' + esc(label) + '"' : "") + ">" + esc(t) + (n && !on ? " <span>" + n + "</span>" : "") + "</a>";
  }

  function parentOf(dir) { return dirOf(dir); }

  function sidebar(dir, activeId, onCategory) {
    var items = [];
    if (dir) {
      var parent = parentOf(dir);
      items.push('<li><a class="menu-link menu-up" href="' + (parent ? dirHref(parent) : "#/") + '">' + esc(parent ? dirTitle(parent) : "All documentation") + "</a></li>");
      items.push('<li class="menu-title"><a href="' + dirHref(dir) + '"' + (onCategory ? ' aria-current="page"' : "") + ">" + esc(dirTitle(dir)) + "</a></li>");
    }
    var pages = pagesIn(dir);
    pages.forEach(function (p) {
      items.push('<li><a class="menu-link" href="' + pageHref(p.id) + '"' + (p.id === activeId ? ' aria-current="page"' : "") + ">" + esc(p.title) + "</a></li>");
    });
    var subs = childDirs(dir);
    if (pages.length && subs.length) items.push('<li class="menu-sep" role="separator"></li>');
    subs.forEach(function (d) {
      items.push('<li><a class="menu-link has-sub" href="' + dirHref(d) + '">' + esc(dirTitle(d)) + "</a></li>");
    });
    return '<nav class="sidebar" id="sidebar" aria-label="Docs sidebar"><ul class="menu">' + items.join("") + "</ul></nav>";
  }
  function withSidebar(dir, activeId, onCategory, main) {
    document.body.classList.remove("no-sidebar");
    return '<div class="docs">' + sidebar(dir, activeId, onCategory) + '<div class="docs-main">' + main + "</div></div>";
  }
  function noSidebar() { document.body.classList.add("no-sidebar"); }

  function breadcrumbs(dir, last) {
    var parts = dir ? dir.split("/") : [];
    var items = ['<li><a href="#/" aria-label="Home">' + ICON_HOME + "</a></li>"];
    parts.forEach(function (_, i) {
      var d = parts.slice(0, i + 1).join("/");
      var isLast = !last && i === parts.length - 1;
      items.push("<li>" + (isLast ? '<span aria-current="page">' + esc(dirTitle(d)) + "</span>" : '<a href="' + dirHref(d) + '">' + esc(dirTitle(d)) + "</a>") + "</li>");
    });
    if (last) items.push('<li><span aria-current="page">' + esc(last) + "</span></li>");
    return '<nav aria-label="Breadcrumbs"><ol class="crumbs">' + items.join("") + "</ol></nav>";
  }

  function renderHome() {
    noSidebar();
    setTitle("");
    var html = '<header class="hero"><div class="container"><h1>Nexus</h1><p>Documentation</p>' +
      '<form class="hero-search" role="search" id="search-hero" autocomplete="off">' + ICON_SEARCH +
      '<label class="sr" for="q-hero">Search documentation</label>' +
      '<input id="q-hero" type="search" placeholder="Search the documentation" spellcheck="false"><kbd aria-hidden="true">/</kbd></form>' +
      '<p class="home-hint">Narrow by tag with <code>tag:coding</code></p></div></header><div class="container home-body">';
    if (!DATA.pages.length) {
      html += '<div class="admonition"><h3>No documentation yet</h3>' +
        "<p>Add a Markdown file such as <code>docs/documentation/coding/from_scratch/rendering/main.md</code>, then run <code>node docs/scripts/build-index.mjs</code>. The GitHub Action does this after you push.</p>" +
        "<p>The page format is described in <code>docs/documentation/README.md</code>.</p></div>";
    } else {
      var top = childDirs("");
      if (top.length) {
        html += "<h2>Categories</h2><ul class=\"features\">" + top.map(function (d) {
          var info = dirInfo(d);
          return '<li><h3><a href="' + dirHref(d) + '">' + esc(dirTitle(d)) + "</a></h3>" +
            (info.description ? "<p>" + esc(info.description) + "</p>" : "") +
            "<small>" + plural(countUnder(d), "page") + "</small></li>";
        }).join("") + "</ul>";
      }
      var loose = pagesIn("");
      if (loose.length) html += "<h2>Pages</h2><ul class=\"doc-list\">" + loose.map(docListItem).join("") + "</ul>";
      var tags = sortedTags();
      if (tags.length) html += "<h2>Tags</h2><ul class=\"tag-list\">" + tags.map(function (t) { return "<li>" + tagBadge(t, tagHref(t)) + "</li>"; }).join("") + "</ul>";
    }
    view.innerHTML = html + "</div>";
    bindSearchInput(document.getElementById("q-hero"), document.getElementById("search-hero"), true);
  }

  function docListItem(p) {
    return '<li><a href="' + pageHref(p.id) + '">' + esc(p.title) + "</a>" + (p.description ? "<p>" + esc(p.description) + "</p>" : "") + "</li>";
  }

  function renderSearch(route) {
    noSidebar();
    var q = route.params.get("q") || "";
    var parsed = parseQuery(q);
    var tags = route.params.getAll("tag").map(function (t) { return t.toLowerCase(); }).concat(parsed.tags);
    tags = tags.filter(function (t, i) { return tags.indexOf(t) === i; });
    var rawQ = q.split(/\s+/).filter(function (t) { return !/^tag:/i.test(t); }).join(" ");
    var res = search(parsed.words, tags);
    setTitle(q ? "Search: " + q : tags.length ? "Tag: " + tags.join(", ") : "Search");

    var counts = {};
    res.hits.forEach(function (h) { h.p.tags.forEach(function (t) { if (tags.indexOf(t) < 0) counts[t] = (counts[t] || 0) + 1; }); });
    var addable = Object.keys(counts).sort(function (a, b) { return counts[b] - counts[a] || collator.compare(a, b); }).slice(0, 12);

    var html = '<div class="container search-page"><h1>' + (rawQ ? "Search results" : tags.length ? "Tagged: " + esc(tags.join(", ")) : "Search results") + "</h1>";
    if (tags.length) {
      html += '<div class="filter-row"><b>Filtering by tag</b>' + tags.map(function (t) {
        return '<a class="tag is-on" href="' + searchHref(rawQ, tags.filter(function (x) { return x !== t; })) + '" title="Remove this tag filter">' + esc(t) + " ×</a>";
      }).join("") + "</div>";
    }
    if (addable.length) {
      html += '<div class="filter-row"><b>' + (tags.length ? "Add tag" : "Tags") + "</b>" + addable.map(function (t) {
        return '<a class="tag" href="' + searchHref(rawQ, tags.concat(t)) + '">' + esc(t) + " <span>" + counts[t] + "</span></a>";
      }).join("") + "</div>";
    }
    if (!res.hits.length) {
      html += '<div class="admonition" style="margin-top:1.25rem"><h3>Nothing matched</h3><p>Try fewer or shorter words' + (tags.length ? ", or remove a tag filter" : "") + ".</p></div>";
    } else {
      html += '<p class="result-count">' + plural(res.hits.length, "page") + (res.partial ? " matching some of your words" : "") + " found</p>";
      html += '<ul class="results">' + res.hits.slice(0, 50).map(function (h) {
        var p = h.p, snip = snippet(p, parsed.words);
        return "<li><h2><a href=\"" + pageHref(p.id) + '">' + highlight(p.title, parsed.words) + "</a></h2>" +
          (p.dir ? '<div class="path">' + esc(crumbPath(p)).replace(/ \/ /g, " › ") + "</div>" : "") +
          (snip ? "<p>" + highlight(snip, parsed.words) + "</p>" : "") + "</li>";
      }).join("") + "</ul>";
      if (res.hits.length > 50) html += '<p class="result-count">Showing the first 50. Add a tag or another word to narrow it down.</p>';
    }
    view.innerHTML = html + "</div>";
  }

  function renderCategory(dir) {
    var info = dirInfo(dir);
    setTitle(dirTitle(dir));
    var pages = pagesIn(dir), subs = childDirs(dir);
    var main = breadcrumbs(dir) + '<div class="cat-head"><h1>' + esc(dirTitle(dir)) + "</h1>" + (info.description ? "<p>" + esc(info.description) + "</p>" : "") + "</div>";
    if (pages.length) main += '<h2 class="list-title">Pages</h2><ul class="doc-list">' + pages.map(docListItem).join("") + "</ul>";
    if (subs.length) main += '<h2 class="list-title">Sections</h2><ul class="doc-list">' + subs.map(function (d) {
      var i = dirInfo(d);
      return '<li><a href="' + dirHref(d) + '">' + esc(dirTitle(d)) + "</a><p>" + (i.description ? esc(i.description) + " " : "") + plural(countUnder(d), "page") + "</p></li>";
    }).join("") + "</ul>";
    if (!pages.length && !subs.length) main += '<div class="admonition"><h3>This category is empty</h3><p>Add a Markdown file in this folder.</p></div>';
    view.innerHTML = withSidebar(dir, null, true, main);
  }

  function renderMissing(path) {
    noSidebar();
    setTitle("Not found");
    view.innerHTML = '<div class="container search-page"><h1>Page not found</h1><div class="admonition"><p>There is no page at <code>' + esc(path) +
      '</code>. Use the search box, or go back <a href="#/">home</a>.</p></div></div>';
  }

  // ---------- markdown ----------
  function resolveRel(href) {
    // returns {path, frag, isMd, isDir} for relative hrefs, or null for anything else
    if (/^[a-z][a-z0-9+.-]*:/i.test(href) || href.indexOf("//") === 0 || href.charAt(0) === "/") return null;
    var m = href.match(/^([^#?]*)([?#].*)?$/);
    var pathPart = m[1], rest = m[2] || "";
    var out = currentDir ? currentDir.split("/") : [];
    pathPart.split("/").forEach(function (seg) {
      if (seg === "" || seg === ".") return;
      if (seg === "..") out.pop(); else out.push(seg);
    });
    var joined = out.join("/");
    return { path: joined, rest: rest, isMd: /\.md$/i.test(pathPart), isDir: /\/$/.test(pathPart) || !/\.[a-z0-9]+$/i.test(pathPart) };
  }
  function fragOf(rest) { var i = rest.indexOf("#"); return i < 0 ? "" : rest.slice(i + 1); }

  var markedReady = false;
  function setupMarked() {
    if (markedReady) return;
    markedReady = true;
    marked.use({
      gfm: true,
      walkTokens: function (tok) {
        if (tok.type === "link") {
          var h = tok.href || "";
          if (h.charAt(0) === "#") { tok.href = "#/" + encPath(currentPageId) + "?h=" + encodeURIComponent(h.slice(1)); return; }
          var r = resolveRel(h);
          if (!r) return;
          var frag = fragOf(r.rest);
          if (r.isMd) tok.href = pageHref(r.path.replace(/\.md$/i, "")) + (frag ? "?h=" + encodeURIComponent(frag) : "");
          else if (r.isDir && DATA.dirs[r.path]) tok.href = dirHref(r.path);
          else if (r.isDir && DATA.byId[r.path]) tok.href = pageHref(r.path) + (frag ? "?h=" + encodeURIComponent(frag) : "");
          else tok.href = CONTENT + encPath(r.path) + r.rest;
        } else if (tok.type === "image") {
          var ri = resolveRel(tok.href || "");
          if (ri) tok.href = CONTENT + encPath(ri.path) + ri.rest;
        }
      }
    });
  }
  var currentPageId = "";

  function stripFrontMatter(src) {
    return src.replace(/^﻿/, "").replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n?/, "");
  }

  function decorateArticle(root) {
    // heading ids, permalinks
    var used = {};
    var heads = [].slice.call(root.querySelectorAll("h1, h2, h3, h4"));
    heads.forEach(function (h) {
      var id = slugify(h.textContent);
      var base = id, n = 2;
      while (used[id]) id = base + "-" + n++;
      used[id] = true;
      h.id = id;
      if (h.tagName !== "H1") {
        var a = document.createElement("a");
        a.className = "hash-link";
        a.href = "#/" + encPath(currentPageId) + "?h=" + encodeURIComponent(id);
        a.textContent = "#";
        a.setAttribute("aria-label", "Direct link to " + h.textContent.replace(/#$/, ""));
        h.appendChild(a);
      }
    });
    // code blocks: highlight + copy button
    [].slice.call(root.querySelectorAll("pre > code")).forEach(function (code) {
      var pre = code.parentNode;
      var m = (code.className || "").match(/language-([\w+-]+)/);
      if (m && window.hljs && hljs.getLanguage(m[1])) { try { hljs.highlightElement(code); } catch (e) {} }
      var wrap = document.createElement("div");
      wrap.className = "code";
      pre.parentNode.insertBefore(wrap, pre);
      wrap.appendChild(pre);
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "copy";
      btn.textContent = "Copy";
      btn.addEventListener("click", function () {
        var done = function () { btn.textContent = "Copied"; setTimeout(function () { btn.textContent = "Copy"; }, 1500); };
        if (navigator.clipboard) navigator.clipboard.writeText(code.textContent).then(done, function () {});
      });
      wrap.appendChild(btn);
    });
    // external links open in a new tab
    [].slice.call(root.querySelectorAll('a[href^="http"]')).forEach(function (a) {
      if (a.host !== location.host) { a.target = "_blank"; a.rel = "noopener noreferrer"; }
    });
    return heads.filter(function (h) { return h.tagName === "H2" || h.tagName === "H3"; });
  }

  function renderPage(id, token) {
    var p = DATA.byId[id];
    setTitle(p.title);
    currentDir = p.dir;
    currentPageId = id;
    var siblings = pagesIn(p.dir);

    var main = '<div class="docs-grid"><div class="docs-col">' + breadcrumbs(p.dir, p.title) +
      '<article class="markdown" id="prose" aria-busy="true"><p>Loading…</p></article><div id="after"></div></div>' +
      '<aside class="toc" id="toc" aria-label="On this page"></aside></div>';
    view.innerHTML = withSidebar(p.dir, id, false, main);

    return fetch(CONTENT + encPath(id) + ".md", { cache: "no-cache" }).then(function (res) {
      if (!res.ok) throw new Error("HTTP " + res.status);
      return res.text();
    }).then(function (src) {
      if (token !== renderToken) return;
      setupMarked();
      var body = stripFrontMatter(src);
      if (!/^\s*#\s+\S/.test(body)) body = "# " + p.title + "\n\n" + body;
      var prose = document.getElementById("prose");
      prose.innerHTML = marked.parse(body, { async: false });
      prose.removeAttribute("aria-busy");
      var heads = decorateArticle(prose);

      var toc = document.getElementById("toc");
      if (heads.length >= 2) {
        toc.innerHTML = "<h2>On this page</h2><ul>" + heads.map(function (h) {
          return '<li class="l' + h.tagName.charAt(1) + '"><a href="#/' + encPath(id) + "?h=" + encodeURIComponent(h.id) + '" data-id="' + esc(h.id) + '">' +
            esc(h.textContent.replace(/#$/, "")) + "</a></li>";
        }).join("") + "</ul>";
        if ("IntersectionObserver" in window) {
          var links = {};
          [].forEach.call(toc.querySelectorAll("a"), function (a) { links[a.dataset.id] = a; });
          tocObserver = new IntersectionObserver(function (entries) {
            entries.forEach(function (e) {
              if (!e.isIntersecting) return;
              [].forEach.call(toc.querySelectorAll(".is-active"), function (x) { x.classList.remove("is-active"); });
              if (links[e.target.id]) links[e.target.id].classList.add("is-active");
            });
          }, { rootMargin: "-72px 0px -70% 0px" });
          heads.forEach(function (h) { tocObserver.observe(h); });
        }
      } else toc.remove();

      var after = "";
      if (CONFIG.repo) after += '<div class="edit-row"><a href="https://github.com/' + CONFIG.repo + "/edit/" + CONFIG.branch + "/" + CONFIG.contentDir + "/" + encPath(id) + '.md" target="_blank" rel="noopener noreferrer">' + ICON_EDIT + " Edit this page</a></div>";
      var i = siblings.indexOf(p), pag = "";
      if (i > 0) pag += '<a class="prev" href="' + pageHref(siblings[i - 1].id) + '"><small>Previous</small><b>« ' + esc(siblings[i - 1].title) + "</b></a>";
      if (i >= 0 && i < siblings.length - 1) pag += '<a class="next" href="' + pageHref(siblings[i + 1].id) + '"><small>Next</small><b>' + esc(siblings[i + 1].title) + " »</b></a>";
      if (pag) after += '<nav class="pagination" aria-label="Docs pages">' + pag + "</nav>";
      document.getElementById("after").innerHTML = after;
    }).catch(function (err) {
      if (token !== renderToken) return;
      var prose = document.getElementById("prose");
      if (prose) prose.innerHTML = '<div class="admonition"><h3>Could not load this page</h3><p>Expected <code>' + esc(CONTENT + id + ".md") + "</code> (" + esc(err.message) + "). Rebuild the index if you renamed or deleted the file.</p></div>";
    });
  }

  // ---------- search input wiring ----------
  function goSearch(q) {
    var cur = parseRoute();
    var tags = cur.kind === "search" ? cur.params.getAll("tag") : [];
    var url = searchHref(q, tags);
    if (cur.kind === "search") history.replaceState(null, "", url);
    else { prevHash = location.hash || "#/"; history.pushState(null, "", url); }
    render();
  }
  function leaveSearch() {
    history.replaceState(null, "", prevHash && prevHash.indexOf("#/search") !== 0 ? prevHash : "#/");
    render();
  }
  function bindSearchInput(input, form, fromHero) {
    if (!input) return;
    input.addEventListener("input", function () {
      var v = input.value;
      if (!v.trim()) { if (parseRoute().kind === "search") leaveSearch(); return; }
      goSearch(v);
      if (fromHero) { topInput.focus(); try { topInput.setSelectionRange(v.length, v.length); } catch (e) {} }
    });
    input.addEventListener("keydown", function (e) {
      if (e.key === "Escape") {
        if (input.value) { input.value = ""; if (parseRoute().kind === "search") leaveSearch(); }
        else input.blur();
      }
    });
    form.addEventListener("submit", function (e) { e.preventDefault(); input.blur(); });
  }

  // ---------- startup ----------
  function showFatal(msg) {
    view.innerHTML = '<div class="error"><h2>Documentation could not load</h2>' + msg + "</div>";
  }
  function start() {
    var repoLink = document.getElementById("repo-link");
    if (CONFIG.repo) {
      repoLink.href = "https://github.com/" + CONFIG.repo; repoLink.hidden = false;
      var gh = document.getElementById("nav-gh"); gh.href = repoLink.href; gh.hidden = false;
    }

    var menuBtn = document.getElementById("menu-btn");
    function setDrawer(open) {
      document.body.classList.toggle("sidebar-open", open);
      menuBtn.setAttribute("aria-expanded", open ? "true" : "false");
    }
    menuBtn.addEventListener("click", function () { setDrawer(!document.body.classList.contains("sidebar-open")); });
    document.getElementById("backdrop").addEventListener("click", function () { setDrawer(false); });
    window.addEventListener("hashchange", function () { setDrawer(false); });
    bindSearchInput(topInput, document.getElementById("search-top"), false);
    document.addEventListener("keydown", function (e) {
      var tag = (e.target.tagName || "").toLowerCase();
      if (e.key === "/" && !e.ctrlKey && !e.metaKey && !e.altKey && tag !== "input" && tag !== "textarea" && !e.target.isContentEditable) {
        e.preventDefault();
        (document.getElementById("q-hero") || topInput).focus();
      }
    });
    // in-page anchors (TOC and heading permalinks): scroll without re-rendering
    view.addEventListener("click", function (e) {
      var a = e.target.closest && e.target.closest("a.hash-link, .toc a");
      if (!a) return;
      e.preventDefault();
      var el = document.getElementById(new URL(a.href).hash.split("h=")[1] ? decodeURIComponent(new URL(a.href).hash.split("h=")[1]) : "");
      if (el) { history.replaceState(null, "", a.getAttribute("href")); el.scrollIntoView(); }
    });
    window.addEventListener("hashchange", render);

    fetch(CONTENT + "manifest.json", { cache: "no-cache" }).then(function (res) {
      if (!res.ok) throw new Error("HTTP " + res.status);
      return res.json();
    }).then(function (m) {
      DATA = prepare(m);
      render();
    }).catch(function (err) {
      var hint = location.protocol === "file:"
        ? "<p>Browsers block loading files when a page is opened straight from disk. Start a tiny local server from the <code>docs</code> folder, for example <code>python -m http.server</code>, and open <code>http://localhost:8000</code>.</p>"
        : "<p>Could not read <code>" + esc(CONTENT) + "manifest.json</code> (" + esc(err.message) + "). Generate it with <code>node docs/scripts/build-index.mjs</code> and commit it.</p>";
      showFatal(hint);
    });
  }
  start();
})();
